// Airport data (generated by tools/build_geodata.py from OurAirports + Overture/OSM) and
// paved-surface lookup used for tyre friction.

export interface RunwayEnd {
  ident: string;
  x: number; // east, m
  y: number; // north, m
  elev: number; // m MSL (published threshold elevation)
  displaced: number; // m
  hdgTrue: number; // deg
}

export interface Runway {
  id: string;
  width: number;
  length: number;
  surface: string;
  ends: [RunwayEnd, RunwayEnd];
}

export interface AirportData {
  icao: string;
  name: string;
  arp: { lat: number; lon: number; elev: number };
  runways: Runway[];
  runwayLines: { cls: string; pts: [number, number][] }[];
  taxiways: [number, number][][];
  aprons: [number, number][][];
  /** Derived GA parking positions [east, north, heading deg true] (tools/derive_stands.py). */
  stands: [number, number, number][];
  /** Raw OSM gate points (terminal facade). */
  gates?: [number, number][];
  boundary: [number, number][];
  buildings: { h: number; pts: [number, number][] }[];
  frequencies: Record<string, number>;
  navaids: { id: string; type: string; khz: number; lat: number; lon: number; x: number; y: number }[];
}

export const TAXIWAY_HALF_WIDTH = 11.5;

interface Seg { ax: number; ay: number; bx: number; by: number }

function segDist2(px: number, py: number, s: Seg) {
  const dx = s.bx - s.ax, dy = s.by - s.ay;
  const l2 = dx * dx + dy * dy;
  let t = l2 > 0 ? ((px - s.ax) * dx + (py - s.ay) * dy) / l2 : 0;
  t = t < 0 ? 0 : t > 1 ? 1 : t;
  const ex = s.ax + dx * t - px, ey = s.ay + dy * t - py;
  return ex * ex + ey * ey;
}

function inPoly(poly: [number, number][], x: number, y: number) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const [xi, yi] = poly[i], [xj, yj] = poly[j];
    if ((yi > y) !== (yj > y) && x < ((xj - xi) * (y - yi)) / (yj - yi) + xi) inside = !inside;
  }
  return inside;
}

/** Fast point-in-pavement test for an airport. */
export class PavementIndex {
  private segs: Seg[] = [];
  private segHalf: number[] = [];
  private grid = new Map<number, number[]>();
  private polys: { poly: [number, number][]; minX: number; maxX: number; minY: number; maxY: number }[] = [];
  private cell = 50;

  constructor(ap: AirportData) {
    for (const rw of ap.runways) {
      const [a, b] = rw.ends;
      // include 60 m beyond each end (stopways / blast pads)
      const dx = b.x - a.x, dy = b.y - a.y, L = Math.hypot(dx, dy);
      const ux = dx / L, uy = dy / L;
      this.addSeg({ ax: a.x - ux * 60, ay: a.y - uy * 60, bx: b.x + ux * 60, by: b.y + uy * 60 }, rw.width / 2 + 1.5);
    }
    for (const line of ap.taxiways) {
      for (let i = 0; i + 1 < line.length; i++) {
        this.addSeg({ ax: line[i][0], ay: line[i][1], bx: line[i + 1][0], by: line[i + 1][1] }, TAXIWAY_HALF_WIDTH);
      }
    }
    for (const poly of ap.aprons) {
      const xs = poly.map((p) => p[0]), ys = poly.map((p) => p[1]);
      this.polys.push({ poly, minX: Math.min(...xs), maxX: Math.max(...xs), minY: Math.min(...ys), maxY: Math.max(...ys) });
    }
  }

  private addSeg(s: Seg, half: number) {
    const id = this.segs.length;
    this.segs.push(s);
    this.segHalf.push(half);
    const c = this.cell;
    const x0 = Math.floor((Math.min(s.ax, s.bx) - half) / c), x1 = Math.floor((Math.max(s.ax, s.bx) + half) / c);
    const y0 = Math.floor((Math.min(s.ay, s.by) - half) / c), y1 = Math.floor((Math.max(s.ay, s.by) + half) / c);
    for (let ix = x0; ix <= x1; ix++) for (let iy = y0; iy <= y1; iy++) {
      const k = (ix + 32768) * 65536 + iy + 32768;
      let l = this.grid.get(k);
      if (!l) { l = []; this.grid.set(k, l); }
      l.push(id);
    }
  }

  isPaved(x: number, y: number): boolean {
    const k = (Math.floor(x / this.cell) + 32768) * 65536 + Math.floor(y / this.cell) + 32768;
    const l = this.grid.get(k);
    if (l) for (const id of l) {
      const h = this.segHalf[id];
      if (segDist2(x, y, this.segs[id]) <= h * h) return true;
    }
    for (const p of this.polys) {
      if (x < p.minX || x > p.maxX || y < p.minY || y > p.maxY) continue;
      if (inPoly(p.poly, x, y)) return true;
    }
    return false;
  }
}

/** Runway end lookup helpers. */
export function runwayEnd(ap: AirportData, ident: string): { rw: Runway; end: RunwayEnd; other: RunwayEnd } {
  for (const rw of ap.runways) {
    const i = rw.ends.findIndex((e) => e.ident === ident);
    if (i >= 0) return { rw, end: rw.ends[i], other: rw.ends[1 - i] };
  }
  throw new Error(`runway ${ident} not found`);
}
